package com.android.tools.lint.checks;

import static com.android.tools.lint.detector.api.Lint.stripPrefix;

import com.android.tools.lint.detector.api.Category;
import com.android.tools.lint.detector.api.Detector;
import com.android.tools.lint.detector.api.Implementation;
import com.android.tools.lint.detector.api.Issue;
import com.android.tools.lint.detector.api.Location;
import com.android.tools.lint.detector.api.Scope;
import com.android.tools.lint.detector.api.Severity;
import com.android.tools.lint.detector.api.XmlContext;
import com.android.tools.lint.detector.api.XmlScanner;
import java.util.Arrays;
import java.util.Collection;
import java.util.Collections;
import java.util.HashSet;
import java.util.Locale;
import java.util.Set;
import org.w3c.dom.Element;

public class ManifestTypoDetector extends Detector implements XmlScanner {

    private static final String MANIFEST_FILE = "AndroidManifest.xml";

    public static final Issue ISSUE = Issue.create(
            "ManifestTypo",
            "Possible typo in Android manifest tag",
            "This check looks through the AndroidManifest.xml and flags tags that look " +
                    "like likely misspellings of valid manifest tags.",
            Category.CORRECTNESS,
            6,
            Severity.WARNING,
            new Implementation(ManifestTypoDetector.class, Scope.MANIFEST_SCOPE)
    );

    private static final Set<String> VALID_TAGS = new HashSet<>(Arrays.asList(
            "manifest",
            "application",
            "activity",
            "activity-alias",
            "service",
            "receiver",
            "provider",
            "uses-permission",
            "uses-permission-sdk-23",
            "permission",
            "permission-group",
            "permission-tree",
            "uses-sdk",
            "uses-feature",
            "supports-screens",
            "compatible-screens",
            "supports-gl-texture",
            "instrumentation",
            "uses-library",
            "meta-data",
            "intent-filter",
            "action",
            "category",
            "data",
            "grant-uri-permission",
            "path-permission",
            "package",
            "profileable",
            "queries",
            "provider",
            "receiver",
            "service"
    ));

    @Override
    public Collection<String> getApplicableElements() {
        return XmlScanner.ALL;
    }

    @Override
    public void visitElement(XmlContext context, Element element) {
        if (!context.file.getName().equals(MANIFEST_FILE)) {
            return;
        }
        String tag = element.getLocalName();
        if (tag == null || tag.isEmpty()) {
            tag = stripPrefix(element.getTagName());
        }
        String lower = tag.toLowerCase(Locale.US);
        if (VALID_TAGS.contains(lower)) {
            return;
        }

        String bestMatch = null;
        int bestDistance = Integer.MAX_VALUE;
        for (String valid : VALID_TAGS) {
            int distance = editDistance(lower, valid);
            if (distance < bestDistance) {
                bestDistance = distance;
                bestMatch = valid;
            }
        }

        int threshold = lower.length() <= 4 ? 1 : 2;
        if (bestMatch != null && bestDistance <= threshold && bestDistance > 0) {
            String message = String.format("Tag `%1$s` looks like a typo of `%2$s`", tag, bestMatch);
            Location location = context.getNameLocation(element);
            context.report(ISSUE, element, location, message);
        }
    }

    private static int editDistance(String s, String t) {
        int n = s.length();
        int m = t.length();
        if (n == 0) return m;
        if (m == 0) return n;

        int[] prev = new int[m + 1];
        int[] curr = new int[m + 1];
        for (int j = 0; j <= m; j++) {
            prev[j] = j;
        }
        for (int i = 1; i <= n; i++) {
            curr[0] = i;
            char sc = s.charAt(i - 1);
            for (int j = 1; j <= m; j++) {
                int cost = sc == t.charAt(j - 1) ? 0 : 1;
                curr[j] = Math.min(Math.min(curr[j - 1] + 1, prev[j] + 1), prev[j - 1] + cost);
            }
            int[] tmp = prev;
            prev = curr;
            curr = tmp;
        }
        return prev[m];
    }
}
